-- Generated by Ergasterion from a product declaration. Do not edit by hand.
{{ config(materialized='table') }}

with
quarantined as (
    select
        source_record_id,
        source_fund_id,
        source_valued_on,
        source_nav_usd,
        source_called_capital_usd,
        source_distributed_capital_usd,
        nav_source_system,
        violation_00,
        violation_01
    from {{ ref("investment__fund_nav_resolved__checked") }}
),
violations as (
    select
        'source_record_id_not_null' as rule_name,
        source_record_id,
        source_fund_id,
        source_valued_on,
        source_nav_usd,
        source_called_capital_usd,
        source_distributed_capital_usd,
        nav_source_system
    from quarantined
    where violation_00

    union all

    select
        'source_valued_on_not_null' as rule_name,
        source_record_id,
        source_fund_id,
        source_valued_on,
        source_nav_usd,
        source_called_capital_usd,
        source_distributed_capital_usd,
        nav_source_system
    from quarantined
    where violation_01
)

select
    rule_name,
    source_record_id,
    source_fund_id,
    source_valued_on,
    source_nav_usd,
    source_called_capital_usd,
    source_distributed_capital_usd,
    nav_source_system
from violations
